-- bio_plus shots — CODA «Та самая аптека» (10 shots, same January 2026 evening)
BEGIN;

INSERT INTO shots (id, "projectId", "sceneId", "shotCode", "promptFields", "shotType", "cameraAngle", "cameraMove", "storyBeat", "narrativeFunction", "vignetteSlug", "isBroll", "isIconic", "timeOfDay", "paletteKey", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, p.id, s.id, v.shot_code, v.prompt_fields::jsonb, v.shot_type, v.camera_angle, v.camera_move, v.story_beat, v.narrative_function, v.vignette_slug, v.is_broll, v.is_iconic, v.time_of_day, v.palette_key, NOW(), NOW()
FROM projects p
